from pathlib import Path
p=Path('src/components/GeneratedOutfits.tsx');s=p.read_text(encoding='utf-8');s="import OutfitInspector from './OutfitInspector';\n"+s
s=s.replace("const [url,setUrl]=useState(''),[error,setError]=useState('');","const [url,setUrl]=useState(''),[error,setError]=useState(''),[inspect,setInspect]=useState(false),[renaming,setRenaming]=useState(false),[title,setTitle]=useState(design.name);",1)
s=s.replace('<h4>{design.name}</h4>','''<h4>{title}</h4>{renaming?<form onSubmit={async e=>{e.preventDefault();try{await invoke('generated_outfits_rename',{id:design.id,name:title});setRenaming(false);}catch(e){setError(String(e));}}}><input aria-label="Review name" maxLength={80} value={title} onChange={e=>setTitle(e.target.value)}/><button className="btn" disabled={disabled}>Save name</button><button type="button" className="btn" onClick={()=>{setTitle(design.name);setRenaming(false);}}>Cancel</button></form>:<button className="btn" disabled={disabled} onClick={()=>setRenaming(true)}>Rename</button>}<button className="btn" disabled={!url} onClick={()=>setInspect(true)}>Inspect / compare</button>{inspect&&<OutfitInspector id={design.id} layers={designPreviewLayers(referenceLayers(assets,cfg),url)} onClose={()=>setInspect(false)}/>}''',1)
s=s.replace("const [recoverable,setRecoverable]", "const [query,setQuery]=useState(''),[sort,setSort]=useState('newest');\n const [recoverable,setRecoverable]",1)
s=s.replace('<div className="generated-design-grid">{designs.map(design=>','''<div className="builder-actions"><label>Find a pending design<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search names or design ideas"/></label><label>Sort<select value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="name">Name</option></select></label></div><div className="generated-design-grid">{designs.filter(d=>(d.name+' '+d.prompt).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='oldest'?a.createdAt-b.createdAt:b.createdAt-a.createdAt).map(design=>''')
# stable inspection layer identity to prevent reload loops
p.write_text(s,encoding='utf-8')
p=Path('src/components/OutfitInspector.tsx');s=p.read_text(encoding='utf-8').replace('[id,stage,area,onBody,layers]','[id,stage,area,onBody,layers.map(l=>l.key+\'=\'+l.url).join(\'|\')]');p.write_text(s,encoding='utf-8')
